// src/store/store.ts
import { configureStore } from '@reduxjs/toolkit';
import { useDispatch, useSelector, TypedUseSelectorHook } from 'react-redux';

// Import all reducers from features
import authReducer from '../features/auth/authSlice';
import gameReducer from '../features/games/gameSlice';
import uiReducer from '../features/ui/uiSlice';

// ============================================
// CONFIGURE STORE
// ============================================

export const store = configureStore({
  reducer: {
    auth: authReducer,
    games: gameReducer,
    ui: uiReducer,
  },
  // Optional: Add middleware or devTools config
  devTools: process.env.NODE_ENV !== 'production',
});

// ============================================
// EXPORT TYPES
// ============================================

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

// ============================================
// TYPED HOOKS (For use in components)
// ============================================

export const useAppDispatch: () => AppDispatch = useDispatch;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;

// ============================================
// EXPORT ALL ACTIONS (Convenience)
// ============================================

// Re-export all actions from features
// Correct: Go up one level from /store to /src, then into /features
export { authActions } from './features/auth/AuthSlice';   
export { gameActions } from './features/games/gameSlice';    
export { uiActions } from './features/ui/uiSlice';
